try{$code='require '.var_export(dirname(__DIR__).'/api/lib.php',true).'; echo json_encode(prepare_order("concurrent-test"));';$jobs=[];for($i=0;$i<2;$i++){$pipes=[];$process=proc_open([PHP_BINARY,'-r',$code],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$jobs[]=[$process,$pipes];}$results=[];foreach($jobs as [$process,$pipes]){$out=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);verify_test(proc_close($process)===0,'concurrent dispatch process completed');$results[]=json_decode($out,true,32,JSON_THROW_ON_ERROR);}verify_test($results[0]['id']===$results[1]['id'],'parallel PHP processes return same supplier id');verify_test((int)sql("SELECT COUNT(*) FROM order_events WHERE order_id=? AND event='supplier.simulated'",[$id])->fetchColumn()===1,'one supplier event after parallel transactions');
