}finally{set_setting('mode','simulation');sql('DELETE FROM order_events WHERE order_id=?',[$id]);sql('DELETE FROM order_lines WHERE order_id=?',[$id]);sql('DELETE FROM orders WHERE id=?',[$id]);sql('DELETE FROM audit_logs WHERE entity_id=?',[$id]);}
